<?php
require_once __DIR__.'/../../config/koneksi.php';require_login();require_role('laporan');
$from=(string)($_GET['dari']??date('Y-m-01'));$to=(string)($_GET['sampai']??date('Y-m-d'));$rt=trim((string)($_GET['rt']??''));$rw=trim((string)($_GET['rw']??''));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
$where=['ls.tanggal_laporan BETWEEN ? AND ?'];$params=[$from,$to];if($rt!==''){$where[]='w.rt = ?';$params[]=$rt;}if($rw!==''){$where[]='w.rw = ?';$params[]=$rw;}
$stmt=$pdo->prepare('SELECT ls.status,COUNT(*) jumlah FROM laporan_sampah ls LEFT JOIN warga w ON w.id_warga=ls.id_warga WHERE '.implode(' AND ',$where).' GROUP BY ls.status ORDER BY ls.status');$stmt->execute($params);$waste=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT DATE_FORMAT(ls.tanggal_laporan,'%Y-%m') bulan,COUNT(*) jumlah FROM laporan_sampah ls LEFT JOIN warga w ON w.id_warga=ls.id_warga WHERE ".implode(' AND ',$where).' GROUP BY DATE_FORMAT(ls.tanggal_laporan,\'%Y-%m\') ORDER BY bulan');$stmt->execute($params);$monthly=$stmt->fetchAll();
$region=[];$regionParams=[];if($rt!==''){$region[]='w.rt = ?';$regionParams[]=$rt;}if($rw!==''){$region[]='w.rw = ?';$regionParams[]=$rw;}$regionWhere=$region?' AND '.implode(' AND ',$region):'';
$stmt=$pdo->prepare("SELECT p.status,COUNT(*) jumlah FROM pengaduan p LEFT JOIN warga w ON w.id_warga=p.id_warga WHERE p.tanggal_pengaduan BETWEEN ? AND ?$regionWhere GROUP BY p.status ORDER BY p.status");$stmt->execute(array_merge([$from,$to],$regionParams));$complaints=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT p.status_verifikasi,COUNT(*) jumlah FROM pelanggaran p LEFT JOIN warga w ON w.id_warga=p.id_warga WHERE p.tanggal_kejadian BETWEEN ? AND ?$regionWhere AND p.status_verifikasi IN ('Terverifikasi','Selesai Ditindaklanjuti') GROUP BY p.status_verifikasi ORDER BY p.status_verifikasi");$stmt->execute(array_merge([$from,$to],$regionParams));$violations=$stmt->fetchAll();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Cetak Rekapitulasi Lingkungan</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700&family=Manrope:wght@600;800&display=swap" rel="stylesheet"><style>body{max-width:900px;margin:40px auto;color:#24372d;font:13px 'DM Sans',sans-serif}header{display:flex;justify-content:space-between;border-bottom:2px solid #286a50;padding-bottom:18px}h1{font:800 24px Manrope,sans-serif;margin:0 0 5px}h2{margin:27px 0 9px;font:800 15px Manrope,sans-serif}p{color:#64716a}button{border:0;padding:9px 14px;background:#183d34;color:#fff;cursor:pointer}table{width:100%;border-collapse:collapse}th,td{padding:9px 11px;border:1px solid #dce3dd;text-align:left}th{background:#edf3ed;font-size:10px}.note{margin-top:25px;font-size:10px}@media print{body{margin:0 auto}button{display:none}}</style></head><body><header><div><h1>Rekapitulasi Lingkungan RT/RW</h1><p>Periode <?= e(format_tanggal($from)) ?> sampai <?= e(format_tanggal($to)) ?><?php if($rt):?> · RT <?=e($rt)?><?php endif;?><?php if($rw):?> · RW <?=e($rw)?><?php endif;?></p></div><button onclick="window.print()">Cetak</button></header><h2>Laporan sampah</h2><table><thead><tr><th>Status</th><th>Jumlah laporan</th></tr></thead><tbody><?php foreach($waste as $row):?><tr><td><?=e($row['status'])?></td><td><?= (int)$row['jumlah']?></td></tr><?php endforeach;?><?php if(!$waste):?><tr><td colspan="2">Tidak ada data.</td></tr><?php endif;?></tbody></table><h2>Pengaduan warga</h2><table><thead><tr><th>Status</th><th>Jumlah pengaduan</th></tr></thead><tbody><?php foreach($complaints as $row):?><tr><td><?=e($row['status'])?></td><td><?= (int)$row['jumlah']?></td></tr><?php endforeach;?><?php if(!$complaints):?><tr><td colspan="2">Tidak ada data.</td></tr><?php endif;?></tbody></table><h2>Dugaan pelanggaran terverifikasi</h2><table><thead><tr><th>Status verifikasi</th><th>Jumlah catatan</th></tr></thead><tbody><?php foreach($violations as $row):?><tr><td><?=e($row['status_verifikasi'])?></td><td><?= (int)$row['jumlah']?></td></tr><?php endforeach;?><?php if(!$violations):?><tr><td colspan="2">Tidak ada catatan terverifikasi.</td></tr><?php endif;?></tbody></table><p class="note">Rekap ini tidak menampilkan NIK, nomor KK, nama pelapor, atau identitas warga. Catatan dugaan pelanggaran yang belum terverifikasi tidak dicantumkan.</p></body></html>